import React from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { useAuth } from '../context/AuthContext';
import './Dashboard.css';

export default function Dashboard() {
  const { user, logout } = useAuth();
  const cards = [
    { icon: '🚗', title: 'Explorer', desc: 'Notre collection exclusive', link: '/vehicles', cta: 'Voir les modèles' },
    { icon: '📅', title: 'Essai routier', desc: 'Réservez votre expérience', link: '/contact', cta: 'Réserver' },
    { icon: '⚙️', title: 'Configurer', desc: 'Personnalisez votre futur véhicule', link: '/vehicles', cta: 'Configurer' },
    { icon: '📞', title: 'Conseiller', desc: 'Votre expert vous accompagne', link: '/contact', cta: 'Contacter' },
  ];
  return (
    <main className="page-wrapper dash-page">
      <div className="dash-hero">
        <div className="dash-hero__orb" />
        <div className="container">
          <motion.span className="section-label" initial={{ opacity:0,x:-20 }} animate={{ opacity:1,x:0 }} transition={{ duration:0.6,delay:0.2 }}>Espace Client Privé</motion.span>
          <motion.h1 className="dash-title" initial={{ opacity:0,y:30 }} animate={{ opacity:1,y:0 }} transition={{ duration:0.8,delay:0.3,ease:[0.77,0,0.175,1] }}>
            Bienvenue,<br /><span className="shimmer-text">{user?.firstName} {user?.lastName}</span>
          </motion.h1>
          <motion.p className="dash-email" initial={{ opacity:0 }} animate={{ opacity:1 }} transition={{ delay:0.5 }}>{user?.email}</motion.p>
        </div>
      </div>
      <section className="container dash-body">
        <div className="dash-section">
          <h2 className="dash-section-title">Accès Rapide</h2>
          <div className="dash-cards">
            {cards.map((c,i) => (
              <motion.div key={c.title} className="dash-card"
                initial={{ opacity:0,y:40 }} animate={{ opacity:1,y:0 }}
                transition={{ duration:0.7,delay:0.1+i*0.1 }}
                whileHover={{ y:-8,borderColor:'var(--gold)' }}>
                <span className="dash-card__icon">{c.icon}</span>
                <h3 className="dash-card__title">{c.title}</h3>
                <p className="dash-card__desc">{c.desc}</p>
                <Link to={c.link} className="dash-card__link">{c.cta} →</Link>
              </motion.div>
            ))}
          </div>
        </div>
        <div className="dash-section">
          <h2 className="dash-section-title">Informations du Compte</h2>
          <div className="dash-info">
            {[['Prénom',user?.firstName],['Nom',user?.lastName],['Email',user?.email],['Statut','Client Premium']].map(([l,v]) => (
              <div key={l} className="dash-info-item">
                <span className="dash-info-item__label">{l}</span>
                <span className="dash-info-item__value" style={l==='Statut'?{color:'var(--gold)'}:{}}>{v}</span>
              </div>
            ))}
          </div>
        </div>
        <button onClick={logout} className="dash-logout">Déconnexion</button>
      </section>
    </main>
  );
}
